const esc = s => String(s ?? '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const clean = s => String(s ?? '').replace(/[\u0000-\u001f\u007f]/g,'·');
const defangIp = ip => String(ip ?? '').replace(/\./g,'[.]');
const defangUrl = u => clean(u).replace(/^http/i,'hxxp').replace(/\./g,'[.]');
const nolink = s => clean(s).replace(/:\/\//g,'[://]');
const n = x => Number(x ?? 0).toLocaleString('en-US');
const S = $('ES - week statistics').first().json, T = $('ES - threat-intel summary').first().json, A = $input.first().json;
const t = S.aggregations.this, p = S.aggregations.prev, total = t.doc_count, prevTotal = p.doc_count;
const trend = prevTotal ? `${total >= prevTotal ? '+' : ''}${Math.round((total - prevTotal) / prevTotal * 100)}% vs previous week` : 'first full week';
const protoTotal = t.proto.buckets.reduce((a, b) => a + b.doc_count, 0) || 1;
const proto = t.proto.buckets.map(b => `${esc(b.key)} ${Math.round(b.doc_count / protoTotal * 100)}%`).join(' / ');
const v = T.aggregations.ip.v.buckets.map(b => `${esc(b.key)} ${n(b.doc_count)}`).join(' · ') || '-';
const countries = T.aggregations.ip.c.buckets.map(b => `${esc(b.key)} ${b.doc_count}`).join(', ') || '-';
const fams = T.aggregations.fam.f.buckets.map(b => esc(b.key)).join(', ') || '-';
const end = new Date(), start = new Date(end - 7 * 864e5), d = x => x.toISOString().slice(0, 10);
const list = (arr, f) => arr.length ? arr.map(f).join('\n') : '  -';
const text = [
  `📊 <b>Honeypot weekly threat report</b>`, `<i>${d(start)} → ${d(end)} (UTC)</i>`, '',
  `<b>Activity</b>: ${n(total)} events (${trend}) · ${n(t.ips.value)} attacker IPs · ${n(t.sessions.value)} sessions · ${proto}`,
  `<b>Got in (fake shell)</b>: ${n(t.logins.doc_count)} logins · ${n(t.cmds.doc_count)} commands · ${n(t.files.doc_count)} file drops (${n(t.files.u.value)} unique files)`,
  `<b>New attacker IPs checked</b>: ${v}`, `<b>Top countries</b>: ${countries}`,
  `<b>Malware families seen</b> (${n(T.aggregations.fam.new.doc_count)} new files this week): ${fams}`, '',
  `<b>Top attackers</b>`, list(t.topip.buckets, b => `  <code>${defangIp(b.key)}</code> ${n(b.doc_count)}`),
  `<b>Top usernames accepted</b>: ${t.users.top.buckets.map(b => `<code>${esc(clean(b.key).slice(0, 30))}</code>`).join(', ') || '-'}`,
  `<b>Top passwords tried</b>: ${t.pw.top.buckets.map(b => `<code>${esc(clean(b.key).slice(0, 30))}</code>`).join(', ') || '-'}`,
  `<b>Top commands</b> (attacker data, do not run)`, list(t.cmds.top.buckets, b => `  ${n(b.doc_count)}× <code>${esc(nolink(b.key).slice(0, 70))}</code>`), '',
  `<b>Alerts raised</b>`, list(A.aggregations?.r?.buckets ?? [], b => `  ${n(b.doc_count)}  ${esc(b.key)}`),
].join('\n').slice(0, 4000);
const doc = { '@timestamp': end.toISOString(), period_start: start.toISOString(), period_end: end.toISOString(), events: total, previous_week_events: prevTotal,
  attacker_ips: t.ips.value, sessions: t.sessions.value, logins: t.logins.doc_count, commands: t.cmds.doc_count, file_drops: t.files.doc_count,
  unique_files: t.files.u.value, verdicts: Object.fromEntries(T.aggregations.ip.v.buckets.map(b => [b.key, b.doc_count])),
  families: T.aggregations.fam.f.buckets.map(b => b.key), summary: text.replace(/<[^>]+>/g, '') };
return [{ json: { text, doc } }];
